// Original bounded supplied cases. This catalog never reads or writes learner state.
export const motionChallenges=[{id:'forces',title:'Forces and motion'},{id:'evidence',title:'Read collision evidence'},{id:'design',title:'Choose and revise a design'}];
const signed=n=>n>0?`+${n}`:`${n}`;
function choices(values,correct,turn,feedback){const unique=[...new Set(values)];if(unique.length<3)throw new Error('Supplied items need three distinct authored choices.');const a=unique.slice(0,3);for(let i=0;i<turn%3;i++)a.push(a.shift());return a.map((text,i)=>({id:`choice-${i+1}`,text,meaning:'',outcome:text===correct?'match':'different',feedback}));}
function item(id,prompt,answers,correct,n,guided,hint,example,feedback){return {id,prompt,meaning:'',choices:choices(answers,correct,n,feedback),guided,hint,example,guidedMeaning:'',hintMeaning:'',exampleMeaning:''};}
export const motionForceCases=[{left:4,right:4,velocity:-2},{left:6,right:2,velocity:3},{left:2,right:6,velocity:-1},{left:0,right:4,velocity:0},{left:2,right:8,velocity:1},{left:2,right:2,velocity:2}];
const timeOrders=[[.1,.2,.4],[.3,.6,.15],[.8,.2,.4],[.25,.5,1],[.6,.15,.3],[1,.5,.25]];
export function motionCase(kind,serial){
 if(!motionChallenges.some(c=>c.id===kind)||!Number.isSafeInteger(serial)||serial<1||serial>999999)return null;
 const n=(serial-1)%6,base={id:`investigation-${kind}-${serial}`,title:`${motionChallenges.find(c=>c.id===kind).title} · investigation ${serial}`,meaning:'',teachMeaning:'',adaptive:{version:1,kind,serial,caseId:`${kind}-${n+1}`,concept:kind}};
 if(kind==='forces'){
  const m={...motionForceCases[n],mass:2,seconds:1},net=m.right-m.left,a=net/m.mass,v=m.velocity+a;
  const formula=`${m.right} − ${m.left} = ${signed(net)} N; ${signed(net)} ÷ 2 = ${signed(a)} m/s²; ${signed(m.velocity)} + (${signed(a)} × 1) = ${signed(v)} m/s.`;
  const nums=(x,unit)=>`${signed(x)} ${unit}`;
  return {...base,forceCase:m,intro:`Same 2 kg cart: left force ${m.left} N, right force ${m.right} N; initial velocity ${signed(m.velocity)} m/s. Both forces stay constant for one second.`,teach:'Right is positive; left is negative. Net force = right force − left force. Acceleration = net force ÷ mass; velocity after one second = initial velocity + acceleration × 1 s. Zero acceleration can accompany motion. Vertical forces balance; friction and air resistance are omitted in this one-dimensional toy.',items:[
   item('net','What is the signed net horizontal force?', [nums(net,'N'),nums(net===0?m.right+m.left:-net,'N'),nums(net+2,'N')],nums(net,'N'),n,'With left 8 N and right 2 N, net force is −6 N.','Subtract the leftward magnitude from the rightward magnitude.','With 6 N left and 6 N right, net force is 0 N.',formula),
   item('acceleration','What is the signed acceleration?', [nums(a,'m/s²'),nums(a===m.velocity?a+1:m.velocity,'m/s²'),nums(a===0?(m.velocity===2?-2:2):-a,'m/s²')],nums(a,'m/s²'),n+1,'A net force −6 N on a 2 kg cart gives −3 m/s².','Divide the signed net force by 2 kg. Velocity and acceleration are different quantities.','A cart moving at −4 m/s with net force +8 N has +4 m/s²: acceleration need not share velocity’s sign.',formula),
   item('velocity','What is the velocity after one second?', [nums(v,'m/s'),nums(v===m.velocity?0:m.velocity,'m/s'),nums(v===0?2:(-v===m.velocity?m.velocity-a:-v),'m/s')],nums(v,'m/s'),n+2,'Starting at +4 m/s with acceleration −3 m/s² gives +1 m/s after one second: still moving right.','Add the signed one-second velocity change to the starting velocity.','Starting at −2 m/s with acceleration +3 m/s² gives +1 m/s after one second.',formula)
  ]};
 }
 const speed=[1,2,3,-1,-2,-3][n],times=timeOrders[n],ranks=times.map(t=>[...times].sort((a,b)=>a-b).indexOf(t)),data=times.map((time,i)=>({id:['a','b','c'][i],name:['Pad A','Foam B','Spring C'][i],shape:[0,2,3][ranks[i]]+n%2,time,cost:ranks[i]+1,depth:[1,3,4][ranks[i]],average:Number((2*Math.abs(speed)/time).toFixed(8))}));
 const model={mass:2,startVelocity:speed,endVelocity:0},caption=`same 2 kg cart, ${signed(speed)} m/s → 0 m/s`;
 const common={...base,collisionModel:model,data,intro:`Supplied invented trials: ${caption}. Within this table the same target and measurement method are used. These are model numbers, not real test results.`,teach:'Lasting shape change and stopping time are supplied observations. Lasting deformation is measured after the trial; it is not the stopping distance. Average net stopping-force magnitude = mass × magnitude of velocity change ÷ stopping time. Its direction opposes the starting motion. Within a table, mass and velocity change are controlled. Calculated averages do not establish peak force, injury prevention or durability.'};
 const slow=data.find(d=>d.time===Math.max(...times)),fast=data.find(d=>d.time===Math.min(...times)),middle=data.find(d=>d.cost===2);
 if(kind==='evidence'){
  const cat=(id,prompt,key,k)=>item(id,prompt,['Observation','Model inference','Unsupported claim'],key,k,'A measured stopping time is an observation. A calculated average uses the supplied constant-mass model.','Separate supplied measurements, calculations and things the trials did not measure.','A lower average stopping-force magnitude does not establish a lower peak force.',id==='limit'&&n%2?'The constant-mass model does support an average force calculation from these measurements; peak force and real safety remain unmeasured.':`${key}: use the supplied table and the constant-mass model; peak force and real safety remain unmeasured.`);
  return {...common,items:[cat('shape',`“${slow.name} has a lasting shape change of ${slow.shape} cm.”`,'Observation',n),cat('average',`“${slow.name} has a smaller average net stopping-force magnitude than ${fast.name}, under this model.”`,'Model inference',n+1),cat('limit',n%2?'“We cannot infer anything about average net stopping force from these controlled measurements.”':'“The design with the lowest average force prevents every injury.”','Unsupported claim',n+2)]};
 }
 const initial={cost:3,depth:4},revised=n%2?{cost:2,depth:4}:{cost:3,depth:3};
 const designItem=(id,brief,k,answer)=>item(id,`${brief} Which fitting design has the smallest average net stopping-force magnitude?`,data.map(d=>d.name),answer.name,k,'Filter both token-cost and depth limits first, then compare the calculated average magnitudes among fitting designs.','The longest stopping time helps only if that design satisfies both limits.','A brief allowing only 1 token leaves just the 1-token design. That does not establish real safety.',`${answer.name} fits both limits and has the smallest average magnitude among those that fit; peak force, injury and durability remain unknown.`);
 return {...common,constraints:{initial,revised},items:[designItem('first','Initial brief: cost at most 3 tokens; depth at most 4 cm.',n,slow),designItem('revised',`Revised brief: cost at most ${revised.cost} tokens; depth at most ${revised.depth} cm.`,n+1,middle)],newMessage:`New requirement: cost at most ${revised.cost} tokens; depth at most ${revised.depth} cm. Measurements are unchanged.`,writing:'Explain which designs fit the first brief and how you chose among them. What can these invented trials leave unknown? Your own words are human-read and ungraded.'};
}
